/opt/homebrew/bin/zsh -lc "python3 -B -c 'import pathlib,sqlite3; ps=list(pathlib.Path(\"poc/data\").rglob(\"views.sqlite\")); n=0; print(\"stores found\",len(ps));
for p in ps:
 try:
  c=sqlite3.connect(\"file:\"+str(p)+\"?mode=ro\",uri=True); tabs={x[0] for x in c.execute(\"select name from sqlite_master where type=\\\"table\\\"\")};
  if {\"processing_steps\",\"days_completed\",\"judgements\"} <= tabs:
   a=c.execute(\"select count(*) from processing_steps\").fetchone()[0]; b=c.execute(\"select count(*) from days_completed\").fetchone()[0]; j=c.execute(\"select count(*) from judgements\").fetchone()[0];
   if a and not b and j: n+=1; print(str(p),\"steps\",a,\"judgements\",j) if n<=6 else None
  c.close()
 except sqlite3.Error: pass
print(\"with steps, no completed day and judgements\",n)'"

